"""Clean interpreter entry for the trusted continuation driver."""
import os
from pathlib import Path
import sys

# Invoked with -I -S: no user-site startup code has run. Only trusted engine
# modules are imported before run.py starts the pinned training interpreter.
sys.path.insert(0, str(Path(__file__).resolve().parent))
for name in ('PYTHONPATH', 'PYTHONHOME', 'PYTHONUSERBASE', 'LD_PRELOAD',
             'BASH_ENV', 'ENV', 'CDPATH'):
    os.environ.pop(name, None)
os.environ['PYTHONNOUSERSITE'] = '1'
# Load installed packages only after discarding submission-controlled startup paths.
import site
site.main()
from run import main

if __name__ == '__main__': main()
===== LOADER_CONTRACT =====
"""Trusted bench-side data checks. The editable loader chooses only a path."""
import hashlib
import json
from pathlib import Path


def read_resolved(root, record, resolve):
    root = Path(root).resolve()
    relative = resolve(str(root), dict(record))
    if not isinstance(relative, str):
        raise ValueError('Loader must return a relative file path')
    rel = Path(relative)
    if rel.is_absolute() or '..' in rel.parts:
        raise ValueError('Resolved payload must stay inside the scene dataset')
    path = root / rel
    if not path.resolve().is_relative_to(root):
        raise ValueError('Resolved payload is outside the scene')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != record['sha256']:
        raise ValueError('Resolved content differs from requested logical sample')
    payload = json.loads(raw)
    if payload.get('id') != record['id'] or payload.get('metadata',{}).get('difficulty') != record['difficulty']:
        raise ValueError('Resolved sample identity differs')
    if not isinstance(payload.get('prompt'),list) or 'label' not in payload:
        raise ValueError('Invalid original math payload')
    return payload, relative


def expected_groups(rows, cursor, batch_size, first_step, final_step):
    if not rows or cursor < 0 or batch_size <= 0 or final_step < first_step:
        raise ValueError('Invalid logical sampling plan')
    return {step:[rows[(cursor+(step-first_step)*batch_size+i)%len(rows)]['id']
                  for i in range(batch_size)] for step in range(first_step,final_step+1)}
===== MATERIALIZE =====
"""Install a pinned incident artifact before the agent starts, without training."""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import tarfile

from scene import copy_scene, verify_scene


def sha(path):
    digest=hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda:f.read(8*1024**2),b''):digest.update(block)
    return digest.hexdigest()


def install(source, workspace, prepared, lock):
    source,workspace,prepared=map(Path,(source,workspace,prepared))
    pin=json.loads(Path(lock).read_text())
    destination=prepared/'incident'
    if destination.exists():
        verify_scene(destination)
        if sha(destination/'SCENE.json')!=pin['scene_sha256']:raise ValueError('Installed scene differs from artifact pin')
    elif source.is_dir():
        if sha(source/'SCENE.json')!=pin['scene_sha256']:raise ValueError('Source scene differs from artifact pin')
        copy_scene(source,destination)
    else:
        if sha(source)!=pin['archive_sha256'] or source.stat().st_size!=pin['archive_size']:
            raise ValueError('Scene archive pin mismatch')
        destination.mkdir(parents=True)
        with tarfile.open(source) as archive:archive.extractall(destination,filter='data')
        verify_scene(destination)
        if sha(destination/'SCENE.json')!=pin['scene_sha256']:raise ValueError('Extracted scene differs from pin')
    link=workspace/'incident'
    if link.is_symlink():
        if link.resolve()!=destination.resolve():raise ValueError('Unexpected existing incident link')
    elif link.exists():raise FileExistsError('Workspace incident already exists')
    else:link.symlink_to(destination.resolve(),target_is_directory=True)
    return destination


def main():
    p=argparse.ArgumentParser(description=__doc__)
    for name in ['source','workspace','prepared','lock']:p.add_argument('--'+name,type=Path,required=True)
    args=p.parse_args();print(install(args.source,args.workspace,args.prepared,args.lock))


if __name__=='__main__':main()
